// Compiled only into the isolated APK generated by run.py prepare.
using System;
using System.IO;
using System.Reflection;
using System.Text.Json.Nodes;
using Android.Content;
using LibGit2Sharp;

namespace Unlimotion.Android;

internal static class NativeGitSmokeProbe
{
    internal const string Package = "org.unlimotion.nativegitsmoke";

    internal static string? GetNativeDirectory(Context context, string? actual)
    {
        RequirePackage(context);
        return File.Exists(Path.Combine(External(context), "native-git-smoke-negative"))
            ? Path.Combine(context.FilesDir!.AbsolutePath, "missing-native-git-smoke")
            : actual;
    }

    internal static void Run(Context context)
    {
        RequirePackage(context);
        var report = new JsonObject
        {
            ["schema"] = 1,
            ["runId"] = Guid.NewGuid().ToString("N"),
            ["pid"] = global::Android.OS.Process.MyPid(),
            ["package"] = context.PackageName,
            ["abi"] = global::Android.OS.Build.SupportedAbis?[0],
            ["utc"] = DateTimeOffset.UtcNow.ToString("O"),
            ["nativeDirectory"] = context.ApplicationInfo?.NativeLibraryDir,
            ["negative"] = File.Exists(Path.Combine(External(context), "native-git-smoke-negative")),
            ["success"] = false
        };
        var operations = new JsonArray();
        report["operations"] = operations;
        try
        {
            var before = Handles();
            report["handlesBefore"] = before;
            operations.Add(CommitAndRead(context));
            MainActivity.ConfigureCoreAppServices(context);
            var after = Handles();
            report["handlesAfter"] = after;
            if (before != after || before.Contains("0x0", StringComparison.Ordinal))
                throw new InvalidOperationException("Bootstrap handles missing or changed on repeated Configure.");
            operations.Add(CommitAndRead(context));
            report["success"] = true;
        }
        catch (Exception ex)
        {
            report["error"] = ex.ToString();
            global::Android.Util.Log.Error("NativeGitSmoke", ex.ToString());
        }
        var path = Path.Combine(External(context), "native-git-smoke.json");
        var temporary = path + ".tmp";
        File.WriteAllText(temporary, report.ToJsonString());
        File.Move(temporary, path, true);
    }

    private static JsonObject CommitAndRead(Context context)
    {
        var directory = Path.Combine(context.FilesDir!.AbsolutePath, "native-git-smoke", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        Repository.Init(directory);
        var content = "native Git exact UTF-8 content: проверка " + Guid.NewGuid().ToString("N");
        File.WriteAllText(Path.Combine(directory, "probe.txt"), content);
        string commitId;
        using (var repository = new Repository(directory))
        {
            Commands.Stage(repository, "probe.txt");
            var signature = new Signature("Native Git smoke", "native-git-smoke@invalid.local", DateTimeOffset.UtcNow);
            commitId = repository.Commit("Verify packaged native Git", signature, signature).Sha;
            if (repository.RetrieveStatus().IsDirty)
                throw new InvalidOperationException("Committed repository is dirty.");
        }
        // Reopen the on-disk repository rather than read a retained in-memory tree.
        using (var reopened = new Repository(directory))
        {
            var commit = reopened.Head.Tip;
            if (commit.Sha != commitId || ((Blob)commit.Tree["probe.txt"].Target).GetContentText() != content)
                throw new InvalidOperationException("Persisted commit/blob read-back differs.");
            if (reopened.RetrieveStatus().IsDirty)
                throw new InvalidOperationException("Reopened repository is dirty.");
        }
        return new JsonObject
        {
            ["repository"] = directory, ["commit"] = commitId,
            ["init"] = true, ["staged"] = true, ["committed"] = true,
            ["clean"] = true, ["reopenedExactBlob"] = true
        };
    }

    private static string Handles()
    {
        var type = typeof(MainActivity);
        var crypto = (IntPtr)type.GetField("_gitCryptoHandle", BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
        var ssl = (IntPtr)type.GetField("_gitSslHandle", BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
        return $"crypto=0x{crypto.ToInt64():x};ssl=0x{ssl.ToInt64():x}";
    }

    private static string External(Context context) => context.GetExternalFilesDir(null)!.AbsolutePath;

    private static void RequirePackage(Context context)
    {
        if (context.PackageName != Package)
            throw new InvalidOperationException("Native Git smoke must use its isolated package.");
    }
}
